 $('liveForgotPassword').onclick=async ev=>{ev.preventDefault();const msg=$('liveAuthMessage');if(!$('liveEmail').value.trim()){msg.textContent='Enter your email or nickname above first.';return;}msg.textContent='Sending a password reset link…';try{const{error}=await sb.auth.resetPasswordForEmail(email(),{redirectTo:location.origin+'/reset-password.html'});if(error)throw error;msg.textContent='Check your email for a link to reset your password.';}catch(e){msg.textContent=e.message||'Could not send the reset link.';}};
