 async function loadCommunities(){const host=$('liveCommunities');if(!host)return;const{data,error}=await sb.rpc('mj_list_discoverable_communities');if(error){host.innerHTML=`<p class="live-empty">Communities unavailable: ${esc(error.message)}. Run the live social migration.</p>`;return;}state.communities=data||[];renderCommunities();}
 async function renderCommunities(){
  const host=$('liveCommunities');
  if(host)host.innerHTML=state.communities.map(c=>`<div class="live-community"><h4>${esc(c.name)}</h4><p>${esc(c.topic)} · ${c.is_private?'Private':'Public'}</p><p>${esc(c.description)}</p><button class="mini-btn" data-join-community="${c.id}">${c.approval_required||c.is_private?'Request to join':'Join community'}</button></div>`).join('')||'<p class="live-empty">No communities yet.</p>';
  const pop=$('livePopularSpaces');if(pop)pop.innerHTML=state.communities.slice(0,3).map(c=>`<div class="row-card"><div class="thumb">◎</div><div class="grow"><h4>${esc(c.name)}</h4><p>${esc(c.topic)} · ${c.is_private?'Private':'Public'}</p></div><button class="mini-btn" data-join-community="${c.id}">View</button></div>`).join('')||'<p class="live-empty">No public spaces yet.</p>';
  const mineHost=$('liveMyCommunities');if(!mineHost)return;
  if(!state.session){mineHost.innerHTML='<p class="live-empty">Sign in to see your communities.</p>';return;}
  const{data,error}=await sb.from('mj_community_members').select('community_id,role').eq('user_id',state.session.user.id);
  if(error){mineHost.innerHTML=`<p class="live-empty">Membership list unavailable: ${esc(error.message)}</p>`;return;}
  const memberships=new Map((data||[]).map(m=>[m.community_id,m.role]));
  mineHost.innerHTML=state.communities.filter(c=>memberships.has(c.id)||c.created_by===state.session.user.id).map(c=>{const role=c.created_by===state.session.user.id?'owner':(memberships.get(c.id)||'member');return `<div class="live-community"><h4>${esc(c.name)}</h4><p>${esc(c.topic)} · Your role: ${esc(role==='moderator'?'Admin':role)}</p><button class="mini-btn" data-open-community="${c.id}">Open discussions</button>${role==='owner'||role==='moderator'?`<button class="mini-btn" data-manage-community="${c.id}">Manage members</button>`:''}${role==='owner'?`<button class="mini-btn" data-delete-community="${c.id}">Delete group</button>`:`<button class="mini-btn" data-leave-community="${c.id}">Leave group</button>`}</div>`;}).join('')||'<p class="live-empty">You have not joined any communities yet.</p>';
 }
 async function openCommunityManagement(id){const c=state.communities.find(x=>x.id===id);if(!c)return;const b=modal('Manage '+c.name,`<p class="live-message">Creators can appoint or remove admins. Admins can remove ordinary members only.</p><div id="communityMemberTools"><p class="live-empty">Loading members…</p></div><button class="secondary" id="communityManageClose">Close</button>`);$('communityManageClose').onclick=()=>b.remove();const host=$('communityMemberTools');const{data,error}=await sb.rpc('mj_list_community_members',{p_community_id:id});if(error){host.innerHTML=`<p class="live-message">Could not load members: ${esc(error.message)}. Run the community management SQL first.</p>`;return;}const isOwner=c.created_by===state.session.user.id;host.innerHTML=(data||[]).map(m=>`<div class="live-community"><b>${esc(m.nickname||'Mjadala member')}</b><p>${esc(m.role==='moderator'?'Admin':m.role)}${m.user_id===state.session.user.id?' · You':''}</p>${isOwner&&m.role==='member'?`<button class="mini-btn" data-community-role="${m.user_id}" data-community-id="${id}" data-make-admin="1">Make admin</button>`:''}${isOwner&&m.role==='moderator'?`<button class="mini-btn" data-community-role="${m.user_id}" data-community-id="${id}" data-make-admin="0">Remove admin role</button>`:''}${m.role==='member'&&m.user_id!==state.session.user.id?`<button class="mini-btn" data-community-remove="${m.user_id}" data-community-id="${id}">Remove member</button>`:''}</div>`).join('')||'<p class="live-empty">No members found.</p>';}
 document.addEventListener('click',async e=>{const role=e.target.closest('[data-community-role]');const remove=e.target.closest('[data-community-remove]');if(!role&&!remove)return;const btn=role||remove;btn.disabled=true;try{let result;if(role)result=await sb.rpc('mj_set_community_moderator',{p_community_id:role.dataset.communityId,p_user_id:role.dataset.communityRole,p_make_moderator:role.dataset.makeAdmin==='1'});else result=await sb.rpc('mj_remove_community_member',{p_community_id:remove.dataset.communityId,p_user_id:remove.dataset.communityRemove});if(result.error)throw result.error;toast(role?(role.dataset.makeAdmin==='1'?'Admin role assigned':'Admin role removed'):'Member removed');await openCommunityManagement(btn.dataset.communityId);await renderCommunities();}catch(err){toast('Action failed: '+err.message);btn.disabled=false;}});
 document.addEventListener('click',async e=>{const manage=e.target.closest('[data-manage-community]');const leave=e.target.closest('[data-leave-community]');const del=e.target.closest('[data-delete-community]');if(manage){openCommunityManagement(manage.dataset.manageCommunity);return;}if(leave){if(!confirm('Leave this group? You will need to join again to participate.'))return;leave.disabled=true;const{error}=await sb.rpc('mj_leave_community',{p_community_id:leave.dataset.leaveCommunity});if(error){toast('Could not leave: '+error.message);leave.disabled=false;return;}toast('You left the group');await renderCommunities();return;}if(del){if(!confirm('Delete this group permanently? Its discussions, membership and join requests will also be removed.'))return;del.disabled=true;const{error}=await sb.rpc('mj_delete_community',{p_community_id:del.dataset.deleteCommunity});if(error){toast('Could not delete: '+error.message);del.disabled=false;return;}toast('Group deleted');state.communities=state.communities.filter(c=>c.id!==del.dataset.deleteCommunity);await renderCommunities();}});

 async function loadJoinRequests(){const host=$('liveJoinRequests');if(!host)return;if(!state.session){host.innerHTML='<p class="live-empty">Sign in to view your join requests.</p>';return;}const{data,error}=await sb.rpc('mj_list_community_join_requests');if(error){host.innerHTML=`<p class="live-message">Requests unavailable: ${esc(error.message)}. Apply the private-community discovery migration.</p>`;return;}const rows=data||[],mine=rows.filter(r=>r.is_mine),moderated=rows.filter(r=>r.can_review&&r.status==='pending');const renderOne=r=>{const c=state.communities.find(x=>x.id===r.community_id);return `<div class="live-community"><h4>${esc(c?.name||r.community_name||'Community')}</h4><p>${esc(r.status)} · ${dateText(r.created_at)}</p>${r.is_mine?'<p>Your request</p>':`<p>Join request from ${esc(r.nickname||'a member')}</p><button class="mini-btn" data-review-request="${r.id}" data-decision="approved">Approve</button><button class="mini-btn" data-review-request="${r.id}" data-decision="rejected">Reject</button>`}</div>`;};host.innerHTML='<div class="section-title">Your requests</div>'+(mine.map(renderOne).join('')||'<p class="live-empty">You have no join requests yet.</p>')+'<div class="section-title">Requests awaiting your review</div>'+(moderated.map(renderOne).join('')||'<p class="live-empty">No pending requests for communities you manage.</p>');}
 function showCommunityTab(which){const ids=['communityTabTopics','communityTabMine','communityTabRequests'];ids.forEach(id=>{const b=$(id);if(b){const active=id===({topics:ids[0],mine:ids[1],requests:ids[2]}[which]);b.classList.toggle('on',active);b.setAttribute('aria-selected',String(active));}});const topics=$('liveCommunities'),mine=$('liveMyCommunities'),requests=$('liveJoinRequests');if(topics)topics.hidden=which!=='topics';if(mine)mine.hidden=which!=='mine';if(requests)requests.hidden=which!=='requests';if(which==='requests')loadJoinRequests();}
 $('communityTabTopics')?.addEventListener('click',()=>showCommunityTab('topics'));$('communityTabMine')?.addEventListener('click',()=>showCommunityTab('mine'));$('communityTabRequests')?.addEventListener('click',()=>showCommunityTab('requests'));
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-review-request]');if(!b)return;if(!state.session){authDialog();return;}b.disabled=true;try{const{data,error}=await sb.rpc('mj_review_community_join_request',{p_request_id:b.dataset.reviewRequest,p_decision:b.dataset.decision});if(error)throw error;toast('Request '+b.dataset.decision);await loadJoinRequests();await renderCommunities();}catch(err){toast('Could not review request: '+err.message);b.disabled=false;}});
 async function joinCommunity(id){if(!state.session){authDialog();return;}const c=state.communities.find(x=>x.id===id);if(!c)return;const button=document.querySelector(`[data-join-community="${id}"]`);if(button){button.disabled=true;button.textContent='Working…';}try{if(c.is_private||c.approval_required){const{error}=await sb.rpc('mj_request_community_join',{p_community_id:id});if(error&&/duplicate|unique/i.test(error.message||'')){toast('Your request is already recorded');if(button)button.textContent='Request sent';}else if(error)throw error;else{toast('Join request sent');if(button)button.textContent='Request sent';}}else{const{error}=await sb.from('mj_community_members').insert({community_id:id,user_id:state.session.user.id,role:'member'});if(error&&/duplicate|unique/i.test(error.message||'')){toast('You are already a member');}else if(error)throw error;else toast('Joined community');await renderCommunities();}}catch(e){toast('Could not join: '+e.message);if(button){button.disabled=false;button.textContent=c.approval_required||c.is_private?'Request to join':'Join community';}}}
 async function openCommunity(id){const c=state.communities.find(x=>x.id===id);if(!c)return;if(c.is_private){if(!state.session){authDialog();return;}const{data:member}=await sb.from('mj_community_members').select('community_id').eq('community_id',id).eq('user_id',state.session.user.id).maybeSingle();if(!member&&c.created_by!==state.session.user.id){toast('This is a private community. Request to join and wait for approval.');return;}}const b=modal(c.name,`<p>${esc(c.description)}</p><div id="communityPosts"><p class="live-empty">Loading discussions…</p></div><textarea id="communityPostBody" maxlength="3000" placeholder="Start a discussion in this community…"></textarea><button id="communityPostSend">Publish discussion</button><button class="secondary" id="communityClose">Close</button><p class="live-message" id="communityStatus"></p>`);$('communityClose').onclick=()=>b.remove();async function load(){const{data,error}=await sb.from('mj_posts').select('id,author_id,community_id,topic,body,created_at').eq('community_id',id).order('created_at',{ascending:false}).limit(30);if(error){$('communityPosts').innerHTML=`<p class="live-empty">Could not load discussions: ${esc(error.message)}</p>`;return;}await profileMap((data||[]).map(p=>p.author_id));$('communityPosts').innerHTML=(data||[]).map(p=>`<div class="live-comment"><small><b>${esc(userOf(p.author_id).display_name)}</b> · ${dateText(p.created_at)}</small>${esc(p.body)}<br><button class="secondary" data-community-comment="${p.id}" style="font-size:10px">Open comments</button></div>`).join('')||'<p class="live-empty">No discussions yet. Start the first one.</p>';state.communityPosts=data||[];for(const post of state.communityPosts)state.contextPosts.set(post.id,post);}
 await load();$('communityPostSend').onclick=async()=>{if(!state.session){authDialog();return;}const body=$('communityPostBody').value.trim();if(!body)return;$('communityStatus').textContent='Publishing…';const{error}=await sb.from('mj_posts').insert({author_id:state.session.user.id,community_id:id,topic:c.topic,body});if(error){$('communityStatus').textContent=error.message;return;}$('communityPostBody').value='';$('communityStatus').textContent='Discussion published.';await load();};b.addEventListener('click',e=>{const x=e.target.closest('[data-community-comment]');if(x){const p=(state.communityPosts||[]).find(q=>q.id===x.dataset.communityComment);if(p)state.contextPosts.set(p.id,p);openComments(x.dataset.communityComment);}});}
 document.addEventListener('click',e=>{const join=e.target.closest('[data-join-community]');if(join){joinCommunity(join.dataset.joinCommunity);return;}const open=e.target.closest('[data-open-community]');if(open)openCommunity(open.dataset.openCommunity);});
 async function editProfile(){if(!state.session){authDialog();return;}const current=state.profiles.get(state.session.user.id)||{};const b=modal('Edit your profile',`<label>Display name<input id="editProfileName" maxlength="80" value="${esc(current.nickname||current.display_name||'')}"></label><label>Bio<textarea id="editProfileBio" maxlength="300" placeholder="Tell people a little about yourself">${esc(current.bio||'')}</textarea></label><p class="live-message" id="editProfileStatus"></p><button id="saveProfileChanges">Save changes</button><button class="secondary" id="cancelProfileChanges">Cancel</button>`);$('cancelProfileChanges').onclick=()=>b.remove();$('saveProfileChanges').onclick=async()=>{const nickname=$('editProfileName').value.trim(),bio=$('editProfileBio').value.trim();if(!nickname){$('editProfileStatus').textContent='Display name is required.';return;}const{error}=await sb.from('profiles').update({nickname,bio}).eq('id',state.session.user.id);if(error){$('editProfileStatus').textContent='Could not save: '+error.message;return;}const p={...current,nickname,bio,display_name:nickname};state.profiles.set(state.session.user.id,p);$('liveProfileName').textContent=nickname;$('liveProfileBio').textContent=bio;b.remove();toast('Profile updated');renderFeed();};}
 window.mjadalaLive.editProfile=editProfile;
 // ---------- Quick PIN sign-in (opt-in, for people who struggle to remember a password) ----------
 function quickPinDialog(){
  if(!state.session){authDialog();return;}
  const b=modal('Quick PIN sign-in',`<p class="live-message">Set a 6-digit PIN you can use instead of your password. Anyone who knows this PIN can sign in as you, so keep it private — never use your phone number or birth year.</p><label>Current password<input id="pinCurrentPassword" type="password" autocomplete="current-password"></label><label>New 6-digit PIN<input id="pinNew" inputmode="numeric" maxlength="6" placeholder="e.g. 482915"></label><label>Confirm PIN<input id="pinConfirm" inputmode="numeric" maxlength="6"></label><p class="live-message" id="pinStatus" aria-live="polite"></p><button id="pinSave">Save PIN</button><button class="secondary" id="pinCancel">Cancel</button>`);
  $('pinCancel').onclick=()=>b.remove();
  $('pinSave').onclick=async()=>{
   const current=$('pinCurrentPassword').value,pin=$('pinNew').value.trim(),confirmPin=$('pinConfirm').value.trim();
   if(!/^\d{6}$/.test(pin)){$('pinStatus').textContent='PIN must be exactly 6 digits.';return;}
   if(pin!==confirmPin){$('pinStatus').textContent='The two PINs do not match.';return;}
   if(!current){$('pinStatus').textContent='Enter your current password to confirm this change.';return;}
   $('pinSave').disabled=true;$('pinStatus').textContent='Checking your password…';
   try{
    const{error:reAuthError}=await sb.auth.signInWithPassword({email:state.session.user.email,password:current});
    if(reAuthError)throw new Error('Current password is incorrect.');
    $('pinStatus').textContent='Saving PIN…';
    const{error}=await sb.auth.updateUser({password:pin});
    if(error)throw error;
    toast('Quick PIN saved. Sign in with your email/nickname and this PIN next time.');
    b.remove();
   }catch(e){$('pinStatus').textContent=e.message||'Could not save PIN.';$('pinSave').disabled=false;}
  };
 }
 $('quickPinRow')?.addEventListener('click',quickPinDialog);
 $('quickPinRow')?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();quickPinDialog();}});
 $('createCommunityButton')?.addEventListener('click',()=>{if(!state.session){authDialog();return;}const b=modal('Create a community',`<label>Community name<input id="newCommunityName" maxlength="80" placeholder="e.g. Machakos Makers"></label><label>Topic<select id="newCommunityTopic"><option>Engineering</option><option>Business</option><option>Innovation</option><option>Education</option><option>Technology</option><option>Agriculture</option><option>General</option></select></label><label>Description<textarea id="newCommunityDescription" maxlength="500" placeholder="Explain who the community is for and what members can do"></textarea></label><label><input id="newCommunityPrivate" type="checkbox" style="width:auto"> Private community (join requests need approval)</label><p id="newCommunityStatus" class="live-message"></p><button id="saveNewCommunity">Create community</button><button class="secondary" id="cancelNewCommunity">Cancel</button>`);$('cancelNewCommunity').onclick=()=>b.remove();$('saveNewCommunity').onclick=async()=>{const name=$('newCommunityName').value.trim(),description=$('newCommunityDescription').value.trim(),topic=$('newCommunityTopic').value,is_private=$('newCommunityPrivate').checked;if(name.length<2){$('newCommunityStatus').textContent='Community name must be at least 2 characters.';return;}const slug=name.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70)+'-'+Math.random().toString(36).slice(2,6);const{data,error}=await sb.rpc('mj_create_community',{p_name:name,p_slug:slug,p_description:description,p_topic:topic,p_is_private:is_private});if(error){$('newCommunityStatus').textContent='Could not create: '+error.message;return;}state.communities.push(data);b.remove();await renderCommunities();showCommunityTab('mine');toast('Community created');};});
 // Lightweight profile editor and center-crop canvas. The saved file is the cropped output, not the original.
 function photoDialog(){if(!state.session){authDialog();return;}const b=modal('Choose and crop profile photo',`<p class="live-message">Choose a photo from your gallery or camera, then zoom and reposition it inside the circle.</p><input id="cropFile" type="file" accept="image/*" capture="user"><div class="crop-stage"><canvas id="cropCanvas" width="320" height="320" aria-label="Cropped profile photo preview"></canvas></div><label>Zoom <input id="cropZoom" type="range" min="1" max="3" step="0.05" value="1"></label><label>Horizontal position <input id="cropX" type="range" min="-1" max="1" step="0.01" value="0"></label><label>Vertical position <input id="cropY" type="range" min="-1" max="1" step="0.01" value="0"></label><p id="cropStatus" class="live-message"></p><button id="cropSave">Save cropped photo</button><button id="cropCancel" class="secondary">Cancel</button>`);const canvas=$('cropCanvas'),ctx=canvas.getContext('2d');function draw(){ctx.clearRect(0,0,320,320);ctx.fillStyle='#e8eee8';ctx.fillRect(0,0,320,320);const im=state.cropImage;if(!im)return;const scale=Math.max(320/im.width,320/im.height)*state.cropScale;const w=im.width*scale,h=im.height*scale;const x=(320-w)/2+state.cropX*(w-320)/2,y=(320-h)/2+state.cropY*(h-320)/2;ctx.save();ctx.beginPath();ctx.arc(160,160,158,0,Math.PI*2);ctx.clip();ctx.drawImage(im,x,y,w,h);ctx.restore();} $('cropFile').onchange=()=>{const f=$('cropFile').files?.[0];if(!f)return;if(!f.type.startsWith('image/')){$('cropStatus').textContent='Choose an image file.';return;}if(f.size>12*1024*1024){$('cropStatus').textContent='Choose a photo under 12 MB.';return;}const im=new Image();im.onload=()=>{state.cropImage=im;state.cropScale=1;state.cropX=0;state.cropY=0;draw();};im.onerror=()=>$('cropStatus').textContent='Could not open that image.';im.src=URL.createObjectURL(f);};$('cropZoom').oninput=()=>{state.cropScale=+$('cropZoom').value;draw();};$('cropX').oninput=()=>{state.cropX=+$('cropX').value;draw();};$('cropY').oninput=()=>{state.cropY=+$('cropY').value;draw();};$('cropCancel').onclick=()=>b.remove();$('cropSave').onclick=async()=>{if(!state.cropImage){$('cropStatus').textContent='Choose a photo first.';return;}const btn=$('cropSave');btn.disabled=true;$('cropStatus').textContent='Saving…';try{const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(!blob)throw new Error('Could not create cropped image.');const path=`${state.session.user.id}/${Date.now()}.jpg`;const{error:upErr}=await sb.storage.from('mj-profile-photos').upload(path,blob,{contentType:'image/jpeg',upsert:true});if(upErr)throw upErr;const{data}=sb.storage.from('mj-profile-photos').getPublicUrl(path);const{error}=await sb.from('profiles').update({avatar_url:data.publicUrl}).eq('id',state.session.user.id);if(error)throw error;const avatar=$('profileAvatarButton');avatar.innerHTML=`<img alt="Your profile photo" src="${esc(data.publicUrl)}">`;const p=state.profiles.get(state.session.user.id)||{};p.avatar_url=data.publicUrl;state.profiles.set(state.session.user.id,p);b.remove();toast('Cropped profile photo saved');}catch(e){$('cropStatus').textContent='Could not save: '+e.message;btn.disabled=false;}};}
 $('profileAvatarButton')?.addEventListener('click',photoDialog);$('profilePhotoEdit')?.addEventListener('click',photoDialog);
 function loadProfile(){if(!state.session)return;const id=state.session.user.id;sb.from('profiles').select('id,nickname,avatar_url,bio').eq('id',id).maybeSingle().then(({data,error})=>{if(error){console.warn('Profile unavailable',error.message);return;}if(!data)return;state.profiles.set(id,{...data,display_name:data.display_name||data.nickname||data.full_name||data.username||state.session.user.email?.split('@')[0]||'Mjadala member',username:data.username||state.session.user.email?.split('@')[0]||'member'});$('liveProfileName').textContent=state.profiles.get(id).display_name;$('liveProfileHandle').textContent='@'+state.profiles.get(id).username;$('liveProfileBio').textContent=data.bio||'Welcome to Mjadala';if(data.avatar_url)$('profileAvatarButton').innerHTML=`<img alt="Your profile photo" src="${esc(data.avatar_url)}">`;sb.from('mj_posts').select('id',{count:'exact',head:true}).eq('author_id',id).then(r=>{$('livePostCount').textContent=r.count??0;});sb.from('shorts_creator_follows').select('follower_id',{count:'exact',head:true}).eq('creator_id',id).then(r=>{$('liveFollowerCount').textContent=r.count??0;});sb.from('shorts_creator_follows').select('creator_id',{count:'exact',head:true}).eq('follower_id',id).then(r=>{$('liveFollowingCount').textContent=r.count??0;});});}
 async function heartbeat(){if(!state.session)return;const{error}=await sb.from('mj_user_presence').upsert({user_id:state.session.user.id,last_seen_at:new Date().toISOString(),show_online:true},{onConflict:'user_id'});if(error)console.warn('Presence update skipped:',error.message);else setStatus('Online',true);}
